(() => {
  const header = document.querySelector('header');
  const lockup = document.querySelector('header a');
  const menu = document.querySelector('header [aria-label*="menu" i], header [aria-label*="Menu" i]');
  const headerBtns = [...document.querySelectorAll('header a, header button')].filter(el => {
    const r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0 && getComputedStyle(el).visibility !== 'hidden';
  }).map(el => {
    const r = el.getBoundingClientRect();
    return {
      text: (el.innerText || el.getAttribute('aria-label') || '').trim().slice(0, 40),
      w: Math.round(r.width),
      h: Math.round(r.height),
      left: Math.round(r.left),
      right: Math.round(r.right),
      overflow: el.scrollWidth > el.clientWidth + 1,
    };
  });
  return JSON.stringify({
    vw: innerWidth,
    pageOverflow: document.documentElement.scrollWidth > innerWidth + 2,
    lockup: lockup && { sw: lockup.scrollWidth, cw: lockup.clientWidth, overflow: lockup.scrollWidth > lockup.clientWidth + 1, w: Math.round(lockup.getBoundingClientRect().width) },
    headerBtns,
  }, null, 2);
})()

(() => {
  function measure() {
    const lockup = document.querySelector('header a');
    const visible = [...document.querySelectorAll('header a, header button')].filter(el => {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.opacity !== '0';
    }).map(el => (el.innerText || el.getAttribute('aria-label') || '').trim().slice(0, 30));
    return {
      vw: innerWidth,
      pageOverflow: document.documentElement.scrollWidth > innerWidth + 2,
      lockupOverflow: lockup ? lockup.scrollWidth > lockup.clientWidth + 1 : null,
      lockupW: lockup ? Math.round(lockup.getBoundingClientRect().width) : null,
      visibleHeader: visible,
    };
  }
  return JSON.stringify(measure());
})()

