    h: Math.round(r.height),
    w: Math.round(r.width),
    bottom: Math.round(r.bottom),
  }, null, 2);
})()

async function atWidth(w) {
  await new Promise((r) => {
    // can't resize from here
    r();
  });
  const login=document.getElementById('applyLoginPanel');
  const content=document.getElementById('applyContent');
  if (login) login.hidden = true;
  if (content) content.hidden = false;
  const rail=document.querySelector('.apply-tabs');
  const tabs=[...document.querySelectorAll('.apply-tab')].map(el => {
    const r=el.getBoundingClientRect();
    return { text: el.textContent.trim(), w: Math.round(r.width), h: Math.round(r.height), overflow: el.scrollWidth > el.clientWidth + 1, right: Math.round(r.right) };
  });
  const actions=[...document.querySelectorAll('.apply-toolbar .admin-header-actions a, .apply-toolbar .admin-header-actions button')].map(el => {
    const r=el.getBoundingClientRect();
    return { text: el.textContent.trim(), w: Math.round(r.width), h: Math.round(r.height) };
  });
  return {
    vw: innerWidth,
    pageOverflow: document.documentElement.scrollWidth > innerWidth + 2,
    rail: rail && { overflowX: getComputedStyle(rail).overflowX, scrollWidth: rail.scrollWidth, clientWidth: rail.clientWidth },
    tabs,
    actions,
  };
}
atWidth().then(v => JSON.stringify(v));
